SELECT
    id,
    old_customer_pk      AS "oldCustomerPk",
    old_customer_id      AS "oldCustomerId",
    first_name           AS "firstName",
    middle_name          AS "middleName",
    last_name            AS "lastName",
    street_address       AS "streetAddress",
    city,
    state_us             AS "stateUs",
    zip_code             AS "zipCode",
    phone_number         AS "phoneNumber",
    height,
    weight,
    hair_color           AS "hairColor",
    eye_color            AS "eyeColor",
    race,
    sex,
    marks,
    date_of_birth        AS "dateOfBirth",
    birth_city           AS "birthCity",
    birth_state          AS "birthState",
    birth_country        AS "birthCountry",
    id_type              AS "idType",
    id_number            AS "idNumber",
    id_expiration        AS "idExpiration",
    id_issue_date        AS "idIssueDate",
    ss_number            AS "ssNumber",
    id_address           AS "idAddress",
    id_city              AS "idCity",
    id_state             AS "idState",
    id_zip               AS "idZip",
    employer_name        AS "employerName",
    employer_address     AS "employerAddress",
    employer_city        AS "employerCity",
    employer_state       AS "employerState",
    employer_zip         AS "employerZip",
    employer_phone_number AS "employerPhoneNumber",
    description,
    ffl_number           AS "fflNumber",
    locked,
    tax_id               AS "taxId",
    cell_phone           AS "cellPhone",
    email,
    entered_at           AS "enteredAt",
    military,
    ffl_expire_date      AS "fflExpireDate",
    tax_exempt           AS "taxExempt",
    created_at           AS "createdAt",
    updated_at           AS "updatedAt"
FROM customer
ORDER BY last_name, first_name;